"const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const mysql = require('mysql2/promise'); // Pastikan library mysql2 sudah diinstal (npm install mysql2)
const { onAfterAdminInsertMember } = require('./onAfterAdminInsertMember');

const app = express();
const port = 3000;

// Middleware untuk mem-parsing JSON dan urlencoded data dari body request
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// --- Placeholder Koneksi MySQL Pool ---
const db = mysql.createPool({
    host: 'localhost',
    user: 'root',
    password: '', // Sesuaikan dengan password database Anda
    database: 'apma_database', // Sesuaikan dengan nama database Anda
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0
});

// Memastikan folder 'uploads' tersedia
const uploadDir = path.join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)){
    fs.mkdirSync(uploadDir);
}

// --- Konfigurasi Multer ---
const storage = multer.diskStorage({
    destination: function (req, file, cb) {
        cb(null, 'uploads/');
    },
    filename: function (req, file, cb) {
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        cb(null, file.fieldname + '-' + uniqueSuffix + path.extname(file.originalname));
    }
});

const fileFilter = (req, file, cb) => {
    // Format yang diizinkan: JPG, PNG, PDF
    const allowedFileTypes = /jpeg|jpg|png|pdf/i;
    const extname = allowedFileTypes.test(path.extname(file.originalname).toLowerCase());
    const mimetype = allowedFileTypes.test(file.mimetype);

    if (mimetype && extname) {
        return cb(null, true);
    } else {
        cb(new Error('Format file tidak didukung! Hanya diperbolehkan mengunggah file JPG, PNG, atau PDF.'));
    }
};

const upload = multer({ 
    storage: storage,
    limits: {
        fileSize: 2 * 1024 * 1024 // Batas maksimal 2MB
    },
    fileFilter: fileFilter
});

