    <style>
        :root {
            --primary: #4361ee;
            --secondary: #3f37c9;
            --bg-color: #f8f9fa;
            --text-dark: #2b2d42;
            --text-light: #8d99ae;
            --white: #ffffff;
            --sidebar-width: 250px;
        }
        * { margin: 0; padding: 0; box-sizing: border-box; font-family: 'Inter', sans-serif; }
        body { display: flex; background-color: var(--bg-color); color: var(--text-dark); min-height: 100vh; }

        /* Sidebar */
        .sidebar { width: var(--sidebar-width); background-color: var(--white); padding: 2rem 1rem; box-shadow: 2px 0 10px rgba(0,0,0,0.05); position: fixed; height: 100vh; z-index: 10; }
        .sidebar-brand { font-size: 1.5rem; font-weight: 700; color: var(--primary); text-align: center; margin-bottom: 2rem; }
        .nav-item { padding: 1rem; margin-bottom: 0.5rem; border-radius: 8px; cursor: pointer; transition: all 0.3s ease; font-weight: 600; color: var(--text-light); }
        .nav-item:hover, .nav-item.active { background-color: var(--primary); color: var(--white); }

        /* Main Content */
        .main-content { margin-left: var(--sidebar-width); padding: 2rem 3rem; width: calc(100% - var(--sidebar-width)); }
        .header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 2rem; }
        .header h1 { font-size: 2rem; color: var(--text-dark); }

        /* Tabs */
        .tab-content { display: none; animation: fadeIn 0.4s ease; }
        .tab-content.active { display: block; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }


